// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * A product as a card: picture, optional badge, category, name, rating, summary, price (and the old price struck
 * through when `compareAt` is higher) and an add button. Axes: layout (vertical, horizontal), media (image,
 * none), ratio, rating (show, hide), action (button, none), density.
 */
import { type JSX } from "solid-js";
import { Badge, Block, Box, Button, CardContent, Group, Inline, Link, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { Rating } from "../components/rating";
import { at, cn, fmtMoney, tpl, urlOf } from "../utils";
import type { Product, ProductLabels } from "./product-card.types";

export type ProductCardProps = {
  product: Product;
  labels: ProductLabels;
  badges: Record<string, string>;
  layout?: "vertical" | "horizontal";
  media?: "image" | "none";
  ratio?: "4/3" | "1/1" | "3/4";
  rating?: "show" | "hide";
  action?: "button" | "none";
  density?: "default" | "compact";
  onAdd?: (id: string) => void;
};

export function ProductCard({
  product,
  labels,
  badges,
  layout = "vertical",
  media = "image",
  ratio = "4/3",
  rating = "show",
  action = "button",
  density = "default",
  onAdd,
}: ProductCardProps) {
  return (
    <Block
      tag="article"
      class={cn(
        "flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded",
        "h-full gap-4 overflow-hidden",
        (((layout as string) === "horizontal") ? "flex flex-col sm:flex-row" : "flex flex-col")
      )}
      data-slot="card"
      data-layout={layout}
    >
      {((media as string) === "image") ? (
        <Box class={cn("relative shrink-0", (((layout as string) === "horizontal") ? "sm:w-48" : ""))}>
          <MediaFrame alt={product.name} src={product.image} ratio={ratio} class="h-full" />
          {product.badge ? (
            <Badge variant="default" size="default" class="absolute left-4 top-4">
              {at(badges, product.badge)}
            </Badge>
          ) : null}
        </Box>
      ) : null}
      <CardContent class="flex flex-1 flex-col gap-2">
        <Text size="xs" class="uppercase tracking-wide text-muted-foreground">
          {product.category}
        </Text>
        <Title as={3} size="base" weight="bold">
          {product.href ? (
            <Link href={urlOf(product.href)} variant="default" data-slot="open">
              {product.name}
            </Link>
          ) : (
            <>
              {product.name}
            </>
          )}
        </Title>
        {((rating as string) === "show") ? (
          <Group gap="2">
            <Rating value={product.rating} label={tpl(labels.ratingLabel, product.rating)} />
            <Text size="xs" class="text-muted-foreground">
              {tpl(labels.reviews, product.reviews)}
            </Text>
          </Group>
        ) : null}
        {((density as string) === "default") ? (
          <Text size="sm" class="text-muted-foreground">
            {product.summary}
          </Text>
        ) : null}
        <Group gap="4" justify="between" class="mt-auto pt-2">
          <Group gap="2" align="baseline" class="flex-wrap">
            <Text size="xl" weight="bold">
              {fmtMoney(product.price, product.currency)}
            </Text>
            {(product.compareAt && (product.compareAt > product.price)) ? (
              <Text tag="del" size="sm" class="relative text-muted-foreground" data-slot="compare-at">
                <Inline class="sr-only">
                  {labels.was}
                </Inline>
                {fmtMoney(product.compareAt, product.currency)}
              </Text>
            ) : null}
          </Group>
          {((action as string) === "button") ? (
            <Button
              variant={(product.inStock ? "default" : "outline")}
              size="sm"
              disabled={!product.inStock}
              onClick={() => onAdd?.(product.id)}
            >
              {(product.inStock ? labels.add : labels.soldOut)}
            </Button>
          ) : null}
        </Group>
      </CardContent>
    </Block>
  );
}

// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.

export type Product = {
  id: string;
  name: string;
  summary: string;
  price: number;
  currency: string;
  rating: number;
  reviews: number;
  badge?: string;
  category: string;
  inStock: boolean;
  compareAt?: number;
  href?: string;
  image?: string;
};

export type ProductLabels = {
  add: string;
  soldOut: string;
  reviews: string;
  ratingLabel: string;
  was: string;
  empty: string;
};
